// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import ReleaseSelector from "../index";

const props = {
  marketplace: true,
  versions: [
    { name: "25", value: "25" },
    { name: "21", value: "21" },
  ],
  osOptions: [
    { name: "Linux", value: "linux" },
    { name: "macOS", value: "mac" },
    { name: "Windows", value: "windows" },
    { name: "AIX", value: "aix" },
    { name: "Alpine Linux", value: "alpine_linux" },
  ],
  architectureOptions: [
    { name: "x64", value: "x64" },
    { name: "aarch64", value: "aarch64" },
    { name: "ppc64", value: "ppc64" },
  ],
  defaultVersion: "25",
  defaultOS: "mac",
  defaultArch: "aarch64",
  defaultPackageType: "jdk",
  updateVersion: vi.fn(),
  updateOS: vi.fn(),
  updateArch: vi.fn(),
  updatePackageType: vi.fn(),
};

describe("Marketplace selectors", () => {
  beforeEach(() => vi.clearAllMocks());

  it("uses accessible native controls with the current selected values", async () => {
    const { container } = render(<ReleaseSelector {...props} />);
    expect(screen.getAllByRole("combobox")).toHaveLength(4);
    for (const selector of screen.getAllByRole("combobox"))
      expect(selector).toHaveAccessibleName();
    expect(screen.getByTestId("marketplace-os-selector")).toHaveValue("mac");
    expect(screen.getByTestId("marketplace-arch-selector")).toHaveValue(
      "aarch64",
    );
    expect(screen.getByTestId("marketplace-version-selector")).toHaveValue(
      "25",
    );
    expect(screen.getByTestId("marketplace-package-selector")).toHaveValue(
      "jdk",
    );
    expect(await axe(container)).toHaveNoViolations();
  });

  it("supports three selectors outside Marketplace mode", () => {
    render(<ReleaseSelector {...props} marketplace={false} />);
    expect(screen.getAllByRole("combobox")).toHaveLength(3);
  });

  it("updates platform, version and package type through parent callbacks", () => {
    render(<ReleaseSelector {...props} />);
    fireEvent.change(screen.getByTestId("marketplace-os-selector"), {
      target: { value: "linux" },
    });
    fireEvent.change(screen.getByTestId("marketplace-arch-selector"), {
      target: { value: "x64" },
    });
    fireEvent.change(screen.getByTestId("marketplace-version-selector"), {
      target: { value: "21" },
    });
    fireEvent.change(screen.getByTestId("marketplace-package-selector"), {
      target: { value: "jre" },
    });
    expect(props.updateOS).toHaveBeenCalledWith("linux");
    expect(props.updateArch).toHaveBeenCalledWith("x64");
    expect(props.updateVersion).toHaveBeenCalledWith("21");
    expect(props.updatePackageType).toHaveBeenCalledWith("jre");
  });

  it("reflects reset values from the parent instead of retaining local filter state", () => {
    const { rerender } = render(<ReleaseSelector {...props} />);
    rerender(
      <ReleaseSelector
        {...props}
        defaultOS="any"
        defaultArch="any"
        defaultPackageType="any"
        defaultVersion="21"
      />,
    );
    expect(screen.getByTestId("marketplace-os-selector")).toHaveValue("any");
    expect(screen.getByTestId("marketplace-arch-selector")).toHaveValue("any");
    expect(screen.getByTestId("marketplace-package-selector")).toHaveValue(
      "any",
    );
    expect(screen.getByRole("option", { name: "AIX" })).toBeInTheDocument();
    expect(screen.getByRole("option", { name: "ppc64" })).toBeInTheDocument();
  });

  it("uses Apple Silicon labels and hides architectures incompatible with macOS", () => {
    render(<ReleaseSelector {...props} />);
    expect(
      screen.getByRole("option", { name: "Apple Silicon (aarch64)" }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("option", { name: "Intel (x64)" }),
    ).toBeInTheDocument();
    expect(
      screen.queryByRole("option", { name: "ppc64" }),
    ).not.toBeInTheDocument();
  });

  it("retains a URL-selected version that is not in the LTS shortcut list", () => {
    render(<ReleaseSelector {...props} defaultVersion="27" />);
    expect(screen.getByTestId("marketplace-version-selector")).toHaveValue(
      "27",
    );
  });
});
